"""Embedded SaveSales branding used by the app, HTML exports, and one-file EXEs."""
import base64
from io import BytesIO
from PIL import Image

_LOGO_B64 = ''

def logo_bytes():
    return base64.b64decode(_LOGO_B64)

def logo_pil():
    image = Image.open(BytesIO(logo_bytes())).convert("RGBA")
    image.load()
    return image

def logo_data_uri():
    return "data:image/png;base64," + _LOGO_B64
